package org.eclipse.milo.opcua.stack.core.util;
import java.util.*;
/** Java 8-compatible collection factories. */
public final class Java8Collections { private Java8Collections() {} public static <T> T requireNonNullElse(T a,T b){return a!=null?a:b;} public static <T> java.util.stream.Stream<T> optionalStream(java.util.Optional<T> o){return o.isPresent()?java.util.stream.Stream.of(o.get()):java.util.stream.Stream.empty();} public static <T> java.util.concurrent.CompletableFuture<T> failedFuture(Throwable t){ java.util.concurrent.CompletableFuture<T> f=new java.util.concurrent.CompletableFuture<T>(); f.completeExceptionally(t); return f; } public static <T> List<T> listOf(T...v){return Collections.unmodifiableList(Arrays.asList(v.clone()));} public static <T> List<T> listCopyOf(Iterable<? extends T>v){List<T>r=new ArrayList<T>();for(T x:v)r.add(x);return Collections.unmodifiableList(r);} public static <T> Set<T> setOf(T...v){return Collections.unmodifiableSet(new LinkedHashSet<T>(Arrays.asList(v)));} public static <T> Set<T> setCopyOf(Iterable<? extends T>v){Set<T>r=new LinkedHashSet<T>();for(T x:v)r.add(x);return Collections.unmodifiableSet(r);} public static <K,V> Map<K,V> mapOf(Object...v){Map<K,V>r=new LinkedHashMap<K,V>();for(int i=0;i<v.length;i+=2)r.put((K)v[i],(V)v[i+1]);return Collections.unmodifiableMap(r);} public static <K,V> Map<K,V> mapCopyOf(Map<? extends K,? extends V>v){return Collections.unmodifiableMap(new LinkedHashMap<K,V>(v));}}
